AR.Detector.prototype.codeTable = null;

AR.Detector.prototype.lookupCode = function(bits){
  var code = 0, i, j;
  if (!this.codeTable){
    this.codeTable = {};
    for (i = 0; i < AR.DICT_5X5.length; ++ i){
      this.codeTable[ AR.DICT_5X5[i] ] = i;
    }
  }
  for (i = 0; i < 5; ++ i){
    for (j = 0; j < 5; ++ j){
      code = code * 2 + bits[i][j];
    }
  }
  var id = this.codeTable[code];
  return (id === undefined)? -1: id;
};
